1. Create a new folder `tooltip` in the `components` folder.

2. Inside the `tooltip` folder, create a new file `Tooltip.js`.

3. In the `Tooltip.js` file, create a new React Context.

```javascript
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const openTooltip = (content) => {
    setTooltip({ content, x: event.clientX, y: event.clientY });
  };

  return (
    <TooltipContext.Provider value={{ closeTooltip, openTooltip }}>
      {children}
      {tooltip && (
        <div
          className="tooltip"
          style={{ left: tooltip.x, top: tooltip.y }}
        >
          {tooltip.content}
        </div>
      )}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => useContext(TooltipContext);
```

4. In the `components` folder, create a new file `ButtonWithTooltip.js`.

5. In the `ButtonWithTooltip.js` file, import the `TooltipProvider` and `useTooltip` from the `Tooltip.js` file.

```javascript
import React from 'react';
import TooltipProvider from '../tooltip/TooltipProvider';
import { useTooltip } from '../tooltip/useTooltip';

const ButtonWithTooltip = ({ children, ...props }) => {
  const { openTooltip } = useTooltip();

  const handleMouseOver = (event) => {
    openTooltip(children);
  };

  const handleMouseLeave = useTooltip().closeTooltip;

  return (
    <TooltipProvider>
      <button onMouseOver={handleMouseOver} onMouseLeave={handleMouseLeave} {...props}>
        {children}
      </button>
    </TooltipProvider>
  );
};

export default ButtonWithTooltip;
```

6. Now you can use the `ButtonWithTooltip` component in your pages or components.

```javascript
import ButtonWithTooltip from '../components/ButtonWithTooltip';

export default function Home() {
  return (
    <div>
      <h1>NextJS Tooltip Example</h1>
      <ButtonWithTooltip>Hover over me to see the tooltip</ButtonWithTooltip>
    </div>
  );
}
```

