  chrome.tabs.captureVisibleTab(tab.id, { format: "png" }, (screenshot) => {
    const folder = chrome.storage.local.get("folder", { folder: "screenshots" }).then((result) => result.folder);

    folder.then((folderPath) => {
      const fileName = `screenshot_${new Date().toISOString()}.png`;
      const saveAs = chrome.downloads.create({
        url: screenshot,
        filename: fileName,
        saveAs: true,
        directoryId: chrome.downloads.downloadDirectory,
        downloadFolder: folderPath
      });

      saveAs.then(() => {
        console.log(`Screenshot saved to ${folderPath}/${fileName}`);
      });
    });
  });
});
```

