To compare two Excel files and show discrepancies in Node.js, you can use a library like `xlsx` to read the Excel files and `lodash` for comparison. Here's a simple example:

First, install the necessary dependencies:

```bash
npm install xlsx lodash
```

Then, create a script (e.g., `compareExcel.js`) to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareFiles(file1, file2, sheetName) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const keys1 = _.keys(sheet1);
  const keys2 = _.keys(sheet2);

  const differences = [];

  keys1.forEach((key1) => {
    const value1 = sheet1[key1].v;
    const key2 = _.findIndex(keys2, (key2) => _.startsWith(key2, key1)) + 1;

    if (key2 === keys2.length) {
      differences.push({
        row: Number(key1.split(' ')[1]),
        column: 'A',
        file1: file1,
        value1: value1,
        missingInFile2: true,
      });
    } else {
      const value2 = sheet2[keys2[key2]].v;

      if (value1 !== value2) {
        differences.push({
          row: Number(key1.split(' ')[1]),
          column: key1.split(' ')[0],
          file1: file1,
          value1: value1,
          value2: value2,
        });
      }
    }
  });

  keys2.forEach((key2) => {
    const key1 = _.findIndex(keys1, (key1) => _.startsWith(key1, key2)) + 1;

    if (key1 === keys1.length) {
      differences.push({
        row: Number(key2.split(' ')[1]),
        column: 'A',
        file2: file2,
        missingInFile1: true,
      });
    }
  });

  return differences;
}

// Usage
const differences = compareFiles('file1.xlsx', 'file2.xlsx', 'Sheet1');
console.log(differences);
```

